import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione al calcolo integrale","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ck/cka.md","filePath":"lezioni/c_analisi/ck/cka.md"}`),a={name:`lezioni/c_analisi/ck/cka.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione-al-calcolo-integrale" tabindex="-1">Introduzione al calcolo integrale <a class="header-anchor" href="#introduzione-al-calcolo-integrale" aria-label="Permalink to “Introduzione al calcolo integrale”">​</a></h1><p>Per capire il perché del calcolo integrale facciamo un semplice esempio:</p><p>Consideriamo il grafico della velocità rispetto al tempo in un moto rettilineo uniforme.</p><p>Per conoscere lo spazio percorso quando il tempo è <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> secondi è sufficiente considerare l&#39;area del rettangolo di colore più scuro.</p><p>Similmente, se il moto fosse uniformemente accelerato, la velocità varierebbe in modo costante ed il grafico sarebbe quello a sinistra, e lo spazio al tempo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> sarebbe il trapezio di colore più scuro.</p><p>Se ora consideriamo un moto con accelerazione variabile il grafico della velocità diventa una curva e il calcolo dello spazio percorso si riduce a calcolare l&#39;area del &quot;trapezoide&quot;; così viene chiamata la parte di piano compresa fra il grafico e l&#39;asse delle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> (in figura la parte più scura).</p><p>Se noi riusciamo a calcolare l&#39;area del trapezoide potremo risalire non solo dalla velocità allo spazio, ma anche dall&#39;accelerazione alla velocità, dalla forza al lavoro, eccetera; in pratica saremo capaci di fare l&#39;operazione contraria alla derivazione.</p><p>Approfondiamo ora il problema delle aree.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};